PROGRAM motor_interlock
VAR
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
    Motor : BOOL;
    MotorLatch : BOOL := FALSE;
END_VAR

// Check if emergency stop is activated
IF NOT EStop THEN
    MotorLatch := FALSE;
    Motor := FALSE;
END_IF;

// If emergency stop is not activated, check start and stop conditions
IF EStop THEN
    IF Start AND NOT Stop THEN
        MotorLatch := TRUE;
    ELSIF Stop THEN
        MotorLatch := FALSE;
    END_IF;
END_IF;

// Assign the latch state to the motor output
Motor := MotorLatch;

END_PROGRAM

