PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PrevLevel : INT := 0;
END_VAR

// Check if the level has changed significantly
IF Level <> PrevLevel THEN
    PrevLevel := Level;

    // Turn off the pump if it's on and the level is below the high limit
    IF PumpIn AND (Level < HighLimit) THEN
        PumpIn := FALSE;
    END_IF;

    // Control the inlet pump
    IF Level <= LowLimit THEN
        PumpIn := TRUE;
    ELSIF Level >= HighLimit THEN
        PumpIn := FALSE;
    ELSE
        PumpIn := FALSE;
    END_IF;

    // Control the outlet valve
    IF Level >= HighLimit THEN
        ValveOut := TRUE;
    ELSE
        ValveOut := FALSE;
    END_IF;
END_IF;

// Ensure the pump cannot run if the level is at or above the high limit
IF Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF;
END_PROGRAM

