VAR
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
    HighLimit : INT := 90;
    LowLimit : INT := 10;
END_VAR

// Check for safety condition: PumpIn should never be TRUE when Level >= HighLimit
IF Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF;

// Control logic for PumpIn
IF NOT prev_PumpIn AND Level <= LowLimit THEN
    PumpIn := TRUE;
ELSIF prev_PumpIn AND Level >= HighLimit THEN
    PumpIn := FALSE;
ELSE
    PumpIn := prev_PumpIn;
END_IF;

// Control logic for ValveOut
ValveOut := Level >= HighLimit;

// Update previous states
prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpTimer : TON;
    PrevLevel : INT := 0;
END_VAR

// Check if the level has changed
IF Level <> PrevLevel THEN
    // Reset the timer
    PumpTimer(IN := FALSE);
END_IF;

// Check for overflow condition
IF Level >= 90 THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    // Check for underflow condition
    IF Level <= 10 THEN
        PumpIn := TRUE;
        ValveOut := FALSE;
    ELSE
        // Normal operation
        PumpIn := NOT PumpTimer.Q;
        ValveOut := FALSE;

        // Update timer if pump is on
        IF PumpIn THEN
            PumpTimer(IN := TRUE, PT := T#3s);
        END_IF;
    END_IF;
END_IF;

PrevLevel := Level;
END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL := FALSE;
    DoorB : BOOL := FALSE;
END_VAR

VAR
    PrevOpenA_Cmd : BOOL := FALSE;
    PrevOpenB_Cmd : BOOL := FALSE;
    DoorATimer : TON;
    DoorBTimer : TON;
END_VAR

DoorATimer(IN := OpenA_Cmd AND NOT DoorB, PT := T#1s);
DoorBTimer(IN := OpenB_Cmd AND NOT DoorA, PT := T#1s);

IF NOT OpenA_Cmd AND NOT OpenB_Cmd THEN
    DoorA := FALSE;
    DoorB := FALSE;
ELSIF OpenA_Cmd AND NOT OpenB_Cmd AND NOT DoorA THEN
    DoorA := TRUE;
    DoorB := FALSE;
ELSIF OpenB_Cmd AND NOT OpenA_Cmd AND NOT DoorB THEN
    DoorA := FALSE;
    DoorB := TRUE;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

PrevOpenA_Cmd := OpenA_Cmd;
PrevOpenB_Cmd := OpenB_Cmd;
END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL := FALSE;
    DoorB : BOOL := FALSE;
END_VAR

VAR
    Prev_OpenA_Cmd : BOOL := FALSE;
    Prev_OpenB_Cmd : BOOL := FALSE;
    Timer_A : TON;
    Timer_B : TON;
END_VAR

// Check if the previous state was different from the current state
IF OpenA_Cmd <> Prev_OpenA_Cmd THEN
    Timer_A(IN := NOT OpenA_Cmd, PT := T#1s);
    Prev_OpenA_Cmd := OpenA_Cmd;
END_IF;

IF OpenB_Cmd <> Prev_OpenB_Cmd THEN
    Timer_B(IN := NOT OpenB_Cmd, PT := T#1s);
    Prev_OpenB_Cmd := OpenB_Cmd;
END_IF;

// Control Door A
IF OpenA_Cmd AND NOT OpenB_Cmd AND NOT Timer_A.Q THEN
    DoorA := TRUE;
ELSE
    DoorA := FALSE;
END_IF;

// Control Door B
IF OpenB_Cmd AND NOT OpenA_Cmd AND NOT Timer_B.Q THEN
    DoorB := TRUE;
ELSE
    DoorB := FALSE;
END_IF;
END_PROGRAM

