CASE TRUE OF
    SafetyTimer.Q AND StartPB AND NOT StopPB:
        ConveyorRunning := TRUE;
    StopPB OR NOT SafetyTimer.Q:
        ConveyorRunning := FALSE;
END_CASE;

Conveyor := ConveyorRunning;
END_PROGRAM

