            MotorUp := FALSE;
            IF Not AtTop AND DoorClosed THEN
                TimerDown(IN := TRUE, PT := T#5s);
                IF TimerDown.Q THEN
                    State := 2;
                END_IF;
            END_IF;
        END_IF;

    2: // At-top
        MotorUp := FALSE;
        MotorDown := CallDown AND DoorClosed;
        TimerDown(IN := CallDown AND DoorClosed, PT := T#5s);
        IF TimerDown.Q THEN
            State := 3;
        END_IF;

    3: // Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF AtBottom OR NOT DoorClosed THEN
            MotorDown := FALSE;
            IF Not AtBottom AND DoorClosed THEN
                TimerUp(IN := TRUE, PT := T#5s);
                IF TimerUp.Q THEN
                    State := 0;
                END_IF;
            END_IF;
        END_IF;
END_CASE;

// Safety check: Motors cannot run together
MotorUp := MotorUp AND NOT MotorDown;
MotorDown := MotorDown AND NOT MotorUp;

