    HoldCount : INT := 0;
    TargetHoldCount : INT := 3;
END_VAR

// Check if emergency stop is active
IF NOT EStop THEN
    Motor := FALSE;
    StartTimer(IN := FALSE);
    HoldCount := 0;
ELSE
    // Count holds
    IF StartCmd THEN
        HoldCount := HoldCount + 1;
        IF HoldCount >= TargetHoldCount THEN
            Motor := TRUE;
        ELSE
            Motor := FALSE;
        END_IF;
    ELSE
        Motor := FALSE;
        HoldCount := 0;
    END_IF;

    // Reset timer if not holding
    IF NOT StartCmd OR HoldCount < TargetHoldCount THEN
        StartTimer(IN := FALSE);
    ELSE
        StartTimer(IN := TRUE, PT := T#3s);
    END_IF;
END_IF;

