        IF TimerYellow.TimedOut THEN
            State := 2;
            TimerWalk(IN := TRUE, PT := PT_WALK);
        END_IF;

    2: // Cars Red / Ped Walk
        CarGreen := FALSE;
        CarYellow := FALSE;
        CarRed := TRUE;
