        IF EStop THEN
            State := 0;
        ELSIF StartCycle AND Level < 90 THEN
            State := 1;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF EStop OR Level >= 90 THEN
            State := 2;
        END_IF;

