    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    PumpTimer : TON;
END_VAR

PumpTimer(IN := NOT EStop AND Demand, PT := T#5s);

PrevDemand := Demand;

IF NOT EStop THEN
    IF Demand AND NOT PrevDemand THEN
        Lead := 1 - Lead; // Toggle Lead on rising edge of Demand
    END_IF;

    CASE Lead OF
        0: 
            Pump1 := Demand;
            Pump2 := FALSE;
        1: 
            Pump1 := FALSE;
            Pump2 := Demand;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_CASE;
ELSE
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;

PumpTimer(IN := FALSE); // Reset timer if EStop or no demand
END_PROGRAM

