    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    PumpTimer : TON;
END_VAR

PrevDemand := Demand;

IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Demand AND NOT PrevDemand THEN
        Lead := 1 - Lead; // Toggle lead on rising edge of Demand
    END_IF;

    IF Demand THEN
        IF Lead = 0 THEN
            Pump1 := TRUE;
            Pump2 := FALSE;
        ELSE
            Pump1 := FALSE;
            Pump2 := TRUE;
        END_IF;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_IF;
END_IF;

PumpTimer(IN := Demand, PT := T#5s);
Pump1 := Pump1 AND PumpTimer.Q;
Pump2 := Pump2 AND PumpTimer.Q;
